// Native gameplay tests. Creates its own disposable WebDriver session; localhost only.
// Start the browser driver yourself. This runner never enables Safari automation.
import assert from 'node:assert/strict';
import {mkdirSync,writeFileSync,existsSync,readFileSync} from 'node:fs';
import * as E from '../dist/engine.js';
import {ARCHIVED_PRODUCTS} from '../dist/catalog.js';
import {spatialLayout} from '../dist/spatial-layout.js';
import {personStop} from '../dist/free-navigation.js';
const args=Object.fromEntries(process.argv.slice(2).map(v=>{const i=v.indexOf('=');return [v.slice(0,i).replace(/^--/,''),v.slice(i+1)];}));
const browser=args.browser||'firefox',driver=args.driver||'http://127.0.0.1:4445',base=args.base||'http://127.0.0.1:4318/Mallside/';
assert.ok(['safari','firefox'].includes(browser));
for(const url of [driver,base])assert.ok(['127.0.0.1','localhost','[::1]'].includes(new URL(url).hostname),'Disposable recovery QA requires localhost endpoints.');
if(args.list==='true'){
 const own=readFileSync(new URL(import.meta.url),'utf8'),names=[...E.LOCALS.flatMap(p=>[1,2].map(v=>p.name+' · shared activity '+v+' choices, saved continuation and daily limit')),...[...own.matchAll(/await check\('([^']+)'/g)].map(m=>m[1]).filter(n=>!n.startsWith('no captured'))];
 assert.equal(new Set(names).size,names.length);console.log(JSON.stringify(names));process.exit(0);
}
const release=await fetch(base+'release.json').then(r=>{if(!r.ok)throw Error('Compiled release metadata is unavailable.');return r.json();});
let session=args.session,capabilities,ws,sequence=0;const results=[],errors=[],resourceWarnings=[],viewports=[],inputRetries=[];
async function request(method,path,body){if(args.trace==='true')console.log(JSON.stringify({driver:method+' '+path}));const response=await fetch(driver+path,{method,headers:{'Content-Type':'application/json'},...body?{body:JSON.stringify(body)}:{},signal:AbortSignal.timeout(45000)}),json=await response.json();if(!response.ok||json.value?.error)throw Error(json.value?.message||JSON.stringify(json));return json.value;}
const call=(method,path,body)=>request(method,'/session/'+session+path,body);
const js=(script,...args)=>call('POST','/execute/sync',{script,args});
async function wait(fn,label,timeout=35000){let active=0,previous=Date.now(),last;const deadline=previous+timeout+180000;while(active<timeout&&Date.now()<deadline){const now=Date.now();let visible=true;if(session)try{visible=await js("return document.visibilityState==='visible'");if(!visible){const handle=await call('GET','/window');await call('POST','/window',{handle});visible=await js("return document.visibilityState==='visible'");}}catch(e){last=e;}if(visible)active+=now-previous;previous=now;if(visible)try{const value=await fn();if(value)return value;}catch(e){last=e;}await new Promise(r=>setTimeout(r,150));}throw Error('Timed out: '+label+(last?' · '+last.message:''));}
const exists=selector=>js('return !!document.querySelector(arguments[0])',selector);
const element=selector=>call('POST','/element',{using:'css selector',value:selector});
async function click(selector){
 await wait(()=>exists(selector),selector);await js("document.querySelector(arguments[0]).scrollIntoView({block:'center',inline:'nearest',behavior:'instant'})",selector);
 try{await wait(()=>js("const e=document.querySelector(arguments[0]),r=e.getBoundingClientRect();return r.width>0&&r.height>0&&r.top>=0&&r.bottom<=innerHeight&&e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))",selector),'interactable '+selector,5000);}catch(error){console.error(JSON.stringify(await js("const e=document.querySelector(arguments[0]),r=e.getBoundingClientRect(),hit=document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return {selector:arguments[0],rect:{x:r.x,y:r.y,w:r.width,h:r.height},hit:hit?.outerHTML.slice(0,300),scrollY,innerHeight,visual:{top:visualViewport.offsetTop,height:visualViewport.height}}",selector)));throw error;}
 if(browser==='safari'){
  const before=await js('return window.__qaClicks?.length||0');
  await js("document.querySelector(arguments[0]).focus({preventScroll:true})",selector);await key('\uE007');
  await wait(()=>js('return (window.__qaClicks?.length||0)>arguments[0]',before),'native keyboard activation '+selector,5000);
 }else{const id=(await element(selector))['element-6066-11e4-a52e-4f735466cecf'];await call('POST','/element/'+id+'/click',{});}
}
async function type(selector,text){const id=(await element(selector))['element-6066-11e4-a52e-4f735466cecf'];await call('POST','/element/'+id+'/clear',{});await call('POST','/element/'+id+'/value',{text});}
async function key(value){await call('POST','/actions',{actions:[{type:'key',id:'keyboard',actions:[{type:'keyDown',value},{type:'keyUp',value}]}]});}
let screenBounds,foregroundReleased=false;
async function resize(width,height){const fit=browser==='safari'&&screenBounds;return call('POST','/window/rect',{width:fit?Math.min(width,fit.width):width,height:fit?Math.min(height,fit.height):height,...fit?{x:fit.x,y:fit.y}:{}});}
const stored=()=>js("return JSON.parse(localStorage.getItem('mallside-free'))");
const displayedMinutes=()=>js("const m=document.querySelector('#play-clock').textContent.match(/(\\d+):(\\d+)\\s*(AM|PM)/);if(!m)throw Error('Displayed game clock unavailable');return (Number(m[1])%12+(m[3]==='PM'?12:0))*60+Number(m[2])");
const existsVisible=selector=>js('const e=document.querySelector(arguments[0]);return !!e&&!!e.getClientRects().length',selector);
function fixture(person=null,variant=0,graphics='2d'){
 const s=E.createState();Object.assign(s,{sandbox:true,cash:7500000,day:7,playerName:'Native Gameplay QA',tutorialDone:true,v9Welcome:true});Object.assign(s.preferences,{graphics,motion:'reduced',reducedMotion:true,clockSeconds:3,walkSpeed:1.35});
 s.localStories=E.LOCAL_STORIES.map(d=>({id:d.id,choice:d.choices[variant%2].id,stage:5,active:false,history:Array.from({length:5},(_,stage)=>({stage,day:stage+1,mallId:'orange'}))}));
 const l=spatialLayout(E.mallOf(s),0,E.STORES),point=person?personStop(l.locals.find(n=>n.id===person),l.spawn,l.nav):l.rects.find(r=>r.id==='ross').door;s.mapPosition={...point,mallId:'orange',floor:0};
 if(variant&&person){const a=E.COMPANION_ACTIVITIES.find(a=>a.person===person);s.companionMemories=[{person,activity:a.id,day:6,mallId:'orange',answers:a.steps.map(step=>step.options[0].id)}];}
 return E.validateImport(JSON.stringify(s));
}
async function collect(){if(session&&!ws)errors.push(...await js('return window.__gameQAErrors||[]').catch(()=>[]));}
async function load(){await call('POST','/url',{url:base});await wait(()=>exists('[data-action=resume-game]'),'menu');await js("window.__qaClicks=[];document.addEventListener('click',e=>window.__qaClicks.push({action:e.target.closest('[data-action]')?.dataset.action,tag:e.target.tagName,time:Date.now()}),true);window.__gameQAErrors=[];addEventListener('error',e=>window.__gameQAErrors.push(e.message));addEventListener('unhandledrejection',e=>window.__gameQAErrors.push(String(e.reason)));const old=console.error;console.error=(...args)=>{window.__gameQAErrors.push(args.map(String).join(' '));old.apply(console,args)}");}
async function seed(s){await collect();await call('POST','/url',{url:base+'legal.html'});await wait(()=>js("return location.href.includes('/legal.html')&&document.readyState!=='loading'"),'fixture page ready');await js("for(const key of ['mallside-free','mallside-free-backup'])localStorage.removeItem(key);localStorage.setItem('mallside-free',JSON.stringify(arguments[0]));localStorage.setItem('mallside-mode','free')",s);await load();if(session){const handle=await call('GET','/window');await call('POST','/window',{handle});}console.log(JSON.stringify({visibility:await js('return {visibility:document.visibilityState,focus:document.hasFocus()}')}));if(args['await-foreground']==='true'&&!foregroundReleased){writeFileSync('build/qa/'+browser+'-foreground-ready.json',JSON.stringify({session}));console.log('READY: waiting for foreground signal');await wait(()=>existsSync('build/qa/'+browser+'-foreground-go'),'foreground signal',300000);foregroundReleased=true;}}
async function reload(){await collect();await call('POST','/url',{url:base+'legal.html'});await load();}
async function check(name,fn){if(args.match&&!name.includes(args.match)&&!name.startsWith('no captured'))return;if(args.only==='core'&&(name.startsWith('v32')||name.startsWith('v33')||name.startsWith('v34')||name.startsWith('v35')||name.startsWith('v36')||name.startsWith('v37')||name.startsWith('v38')||name.startsWith('v39')||name.startsWith('v40')||name.startsWith('v41')||name.startsWith('v42')||name.startsWith('v43')||name.startsWith('v44')||name.startsWith('v45')))return;if(args.only==='books'&&!name.startsWith('v38')&&!name.startsWith('no captured'))return;if(args.only==='collection'&&!name.startsWith('v37')&&!name.startsWith('no captured'))return;if(args.only==='lounge'&&!name.startsWith('v36')&&!name.startsWith('no captured'))return;if(args.only==='district'&&!name.startsWith('v35')&&!name.startsWith('no captured'))return;if(args.only==='places'&&!name.startsWith('v34')&&!name.startsWith('no captured'))return;if(args.only==='visual'&&!name.startsWith('v33')&&!name.startsWith('no captured'))return;if(args.only==='commons'&&!name.startsWith('v32')&&!name.startsWith('no captured'))return;if(args.only==='shared'&&!name.includes('shared activity')&&!name.startsWith('no captured'))return;console.log(JSON.stringify({name,status:'running'}));const start=Date.now();await fn();await collect();results.push({name,status:'passed',ms:Date.now()-start});console.log(JSON.stringify(results.at(-1)));}
async function screenshot(name){writeFileSync(`build/qa/${browser}-gameplay-${name}.png`,Buffer.from(await call('GET','/screenshot'),'base64'));}
function planningFixture(group='textile',graphics='3d'){const kinds=({textile:['apparel','bags','shoes'],light:['beauty','jewelry','eyewear'],workshop:['home','books','toys','tech']})[group],st=E.STORES.find(st=>st.mallId==='orange'&&E.isPlanningStore(st)&&kinds.includes(st.businessKind))||E.STORES.find(st=>E.isPlanningStore(st)&&kinds.includes(st.businessKind)),s=fixture(null,0,graphics);s.mallId=st.mallId;s.floor=E.storeFloor(E.mallOf(s),st.id);const l=spatialLayout(E.mallOf(s),s.floor,E.STORES);s.mapPosition={...[...l.rects,...l.units].find(u=>u.id===st.id).door,mallId:s.mallId,floor:s.floor};return {s,st,l};}
