 await click('#play-browse');await click('[data-action=collection-open]');await click('.collection-tools [data-action=studio-open]');await wait(()=>exists('.material-study'),'reopened stocked study');await click('[data-action=studio-palette][data-id=berry]');await click('[data-action=studio-finish][data-id=textured]');const before=await stored(),clock=await displayedMinutes();await click('[data-action=studio-save]');assert.equal(await displayedMinutes(),clock);assert.equal((await stored()).cash,before.cash);assert.equal((await stored()).xp,before.xp);await screenshot('v45-'+type+'-studio');await click('[data-action=back-store]');
